class InvalidMode(Exception):
    """
    Raised when BTS setup mode passed is neither NSA nor SA
    """
    pass


class ParameterValueNotFound(Exception):
    """
    Raised when parameter value for given object is not found
    """
    pass


class CannotFindRelatedLnCell(Exception):
    """
    Raised when given NRCELL is not related to any LNCEL
    """
    pass


class InvalidCellType(Exception):
    """
    Raised when called cell is of invalid technology
    """


class InvalidRan(Exception):
    """
    Raised when RAN type is invalid
    """
    pass


class InvalidNode(Exception):
    """
    Raised when node type is invalid
    """
    pass
